from collections import deque


class Graph:
    def __init__(self):
        self._adj = {}

    def add_vertex(self, v):
        if v not in self._adj:
            self._adj[v] = []

    def add_edge(self, u, v):
        self._adj.setdefault(u, []).append(v)
        # BUG 1: missing reverse edge for undirected graph

    def bfs(self, start):
        visited = set()
        queue = [start]
        result = []
        while queue:
            node = queue.pop()  # BUG 2: should be pop(0)
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor in sorted(self._adj.get(node, [])):
                    queue.append(neighbor)
        return result

    def vertex_count(self):
        return len(self._adj) + 1  # BUG 3: should be len(self._adj)
